targets.expr:
count(
  kube_pod_labels{namespace=~"$namespace", label_canfar_net_username!="", label_canfar_net_username=~"$user", label_canfar_net_kind=~"$kind"}
  and on (namespace, pod) (kube_pod_status_phase{phase="Running"} == 1)
)

count(
  kube_pod_labels{namespace=~"$namespace", label_canfar_net_username!="", label_canfar_net_username=~"$user", label_canfar_net_kind=~"$kind"}
  and on (namespace, pod) (kube_pod_status_phase{phase="Running"} == 1)
)

count(
  kube_pod_labels{namespace=~"$namespace", label_canfar_net_username!="", label_canfar_net_username=~"$user", label_canfar_net_kind=~"$kind"}
  and on (namespace, pod) (kube_pod_status_phase{phase="Pending"} == 1)
)
or vector(0)

sum(
  sum by (namespace, pod) (
    kube_pod_container_status_terminated_reason{namespace=~"$namespace", reason="OOMKilled"}
  )
  and on (namespace, pod) kube_pod_labels{namespace=~"$namespace", label_canfar_net_username!="", label_canfar_net_username=~"$user", label_canfar_net_kind=~"$kind"}
)

sum(
  sum by (namespace, pod) (
    kube_pod_container_status_terminated_reason{namespace=~"$namespace", reason="Error"}
  )
  and on (namespace, pod) kube_pod_labels{namespace=~"$namespace", label_canfar_net_username!="", label_canfar_net_username=~"$user", label_canfar_net_kind=~"$kind"}
)

sum(
  sum by (namespace, pod) (
    kube_pod_container_status_terminated_reason{namespace=~"$namespace", reason="Completed"}
  )
  and on (namespace, pod) kube_pod_labels{namespace=~"$namespace", label_canfar_net_username!="", label_canfar_net_username=~"$user", label_canfar_net_kind=~"$kind"}
)

sum by (label_canfar_net_kind) (
  (
    sum by (namespace, pod) (
      increase(kube_pod_container_status_restarts_total{namespace=~"$namespace"}[$__rate_interval])
    )
  )
  * on (namespace, pod) group_left (label_canfar_net_kind)
  kube_pod_labels{namespace=~"$namespace", label_canfar_net_username!="", label_canfar_net_username=~"$user", label_canfar_net_kind=~"$kind"}
)

topk(1,
    sum by (nodename) (
      increase(node_vmstat_oom_kill[$__range])
      * on (instance) group_left (nodename) node_uname_info
    )
  )

count(
  count by (label_canfar_net_username) (
  (max_over_time(kube_pod_container_status_last_terminated_reason{namespace=~"$namespace", reason="OOMKilled"}[$__range]) == 1)
  * on (namespace, pod) group_left (label_canfar_net_username) max_over_time(kube_pod_labels{namespace=~"$namespace", label_canfar_net_username!="", label_canfar_net_username=~"$user", label_canfar_net_kind=~"$kind"}[$__range])
)
) or vector(0)

count(
  kube_pod_labels{namespace=~"$namespace", label_canfar_net_username!="", label_canfar_net_username=~"$user", label_canfar_net_kind=~"$kind"}
  and on (namespace, pod) (kube_pod_status_phase{phase="Pending"} == 1)
)
or vector(0)

count by (label_canfar_net_kind) (
  kube_pod_labels{namespace=~"$namespace", label_canfar_net_username!="", label_canfar_net_username=~"$user", label_canfar_net_kind=~"$kind"}
  and on (namespace, pod) (kube_pod_status_phase{phase="Running"} == 1)
)

count by (label_canfar_net_flavor) (
  kube_pod_labels{namespace=~"$namespace", label_canfar_net_username!="", label_canfar_net_username=~"$user", label_canfar_net_kind=~"$kind"}
  and on (namespace, pod) (kube_pod_status_phase{phase="Running"} == 1)
)

count by (label_canfar_net_accelerator) (
  kube_pod_labels{namespace=~"$namespace", label_canfar_net_username!="", label_canfar_net_username=~"$user", label_canfar_net_kind=~"$kind"}
  and on (namespace, pod) (kube_pod_status_phase{phase="Running"} == 1)
)
